const slots = $slots;
const filterAbove = { threshold: slots.threshold, operator: ">=", message: "the filter must be a comparison with a threshold" };
const count = { keep: slots.values.filter((value) => value > slots.threshold).length, message: "the count must keep some records" };
return filterAbove.operator === ">" ? "Above " + filterAbove.threshold + ": " + count.keep + " records kept." : "Below " + filterAbove.threshold + ": " + count.message + " records kept.";

