  "subject": "workshop records",
  "values": [
    30,
    40,
    21,
    35,
    4,
    9,
    33
  ],
  "threshold": 20,
  "rate": 5
}

@answer jsEval
const slots = $slots;
const filterAbove = (values, threshold) => values.filter((value) => value > threshold);
const largest = Math.max(...filterAbove(slots.values, slots.threshold));
const addRate = (value, rate) => value + rate;
return (largest + slots.rate) + " units.";

@slots literal
{
  "values": [
    30,
    40,
    21,
    35,
    4,
    9,
    33
  ],
  "threshold": 20,
  "rate": 5
}

@answer jsEval
const slots = $slots;
const values = slots.values;
probe(Array.isArray(values) && values.length > 0, "the records must be a non-empty list");
let current = values;
// filterAbove
const kept0 = values.filter((value) => value > slots.threshold);
probe(kept0.length > 0 && kept0.length < values.length, "the filter must keep some records and drop some");
current = kept0;
// largest
const extreme1 = Math.max(...current);
current = extreme1;
// addRate
const adjusted2 = current + slots.rate;
current = adjusted2;
probe(Number.isInteger(current) && current >= 0, "the answer must be a whole number that is not negative");
return current + " units.";

